const items = $input.all();
// Only email rows researched under the doctrine format ("full || short" cells) that
// passed the research quality gate. Anything else stays in the sheet, untouched.
// Same screenshot-artifact guard as the Email automation extractor, applied again at send time
// so rows written before the guard tightened are also held back.
const ARTIFACT = /counter|statistic|\b0\b|black|blank|placeholder|empty (media )?(box|player|space|area|section|profile|frame|slot)|broken (logo|image|photo|icon|video)|missing (a |an |the )?(logo|image|photo|headshot|picture|icon|video|thumbnail|portrait)|(no|without) (a |any )?(photo|headshot|picture|image|thumbnail|portrait)|carousel|slider|lazy|(not|fail\w*( to)?) load|cut off/i;
// Never pitch an inbox nobody pitches: autoresponders, hiring, billing and press addresses.
const ROLE = /^(noreply|no-reply|donotreply|do-not-reply|jobs|careers|career|hr|recruit\w*|events|media|press|marketing|billing|accounts|webmaster|postmaster|abuse|privacy|legal)$/i;
// A bounced address never reached anyone, so it must not stand in for the clinic.
const BOUNCED = /bounce|undeliver|not delivered|recipient unknown|address not found/i;
// Same reason as the artifact guard below: our own scraper being refused (403 / Cloudflare) is not
// a problem the clinic can see, so never send a first email whose whole claim is that error.
const BLOCKED = /\bforbidden\b|\baccess denied\b|\bcloudflare\b|just a moment|checking your browser|attention required|site can'?t be reached|\b(40\d|5\d{2})\s*(error|forbidden|page|response|status)\b|\b(error|status)\s*(code\s*)?(40\d|5\d{2})\b/i;
const UNREACHABLE = /(site|website|homepage|web ?page|domain)\s+(is\s+)?(currently\s+)?(down|offline|unavailable|inaccessible|unreachable|not\s+(available|accessible|loading|working|reachable|functioning))/i;
const claimOf = j => [j.website_problem, j.recognisable_reason, j.consequence_mechanics].join(' ');

const blank = v => v === undefined || v === null || String(v).trim() === '';
const local = j => String(j['Email Address'] || '').split('@')[0].trim();
const key = j => String(j['Company Name'] || j.Domain || '').trim().toLowerCase();

// Lower rank wins: a named person, then a front-desk style inbox, then anything else.
function rank(j) {
  if (!blank(j['First name'])) return 0;
  if (/^(info|contact|office|hello|smile|frontdesk|front-desk|reception|admin|dental|clinic)$/i.test(local(j))) return 1;
  return 2;
}

const rows = items.map(i => i.json);

// One clinic gets one pitch. Several addresses at the same clinic each got their own email before
// this guard existed (4 at one clinic, 5 at two others) — that reads as spam and costs deliverability.
// A row that bounced is skipped here: nobody read it, so the clinic is still unspoken to and its
// next-best address stays eligible.
const spoken = {};
rows.forEach(j => {
  if (!blank(j.Issues) && BOUNCED.test(String(j.Issues))) return;
  if (!blank(j.ThreadID) || !blank(j.Done) || (!blank(j.Issues) && /replied/i.test(String(j.Issues)))) spoken[key(j)] = true;
});

const unsent = rows.filter(j =>
  blank(j.Done)
  && blank(j.Issues)
  && String(j.website_problem || '').includes(' || ')
  && !blank(j.micro_yes)
  && !blank(j.subject_line)
  && !blank(j['Email Address'])
  && !ARTIFACT.test(String(j.website_problem || ''))
  && !BLOCKED.test(claimOf(j))
  && !UNREACHABLE.test(claimOf(j))
  && !ROLE.test(local(j))
  && !spoken[key(j)]
);

// Best address per clinic, and only one clinic per execution: every downstream $('...').first()
// reference resolves to the last run of its node, so a second lead in the same run corrupts the first.
const best = {};
unsent.forEach(j => {
  const k = key(j);
  if (!best[k] || rank(j) < rank(best[k]) || (rank(j) === rank(best[k]) && Number(j.row_number) < Number(best[k].row_number))) best[k] = j;
});

const picked = Object.keys(best).map(k => best[k]).sort((a, b) => Number(a.row_number) - Number(b.row_number));
return picked.length ? [{ json: picked[0] }] : [];

// FU Pick — candidate rows for a sheet-driven follow-up.
// Follow-ups used to live inside a days-long waiting execution; every one of them was lost when
// the execution died (Gmail credential outage, cancelled run). This branch rebuilds the queue from
// the sheet on every tick instead, so nothing is held in memory between sends.
// Emits up to 12 candidates; FU Decide picks the single one that is actually due.
const ARTIFACT = /counter|statistic|\b0\b|black|blank|placeholder|empty (media )?(box|player|space|area|section|profile|frame|slot)|broken (logo|image|photo|icon|video)|missing (a |an |the )?(logo|image|photo|headshot|picture|icon|video|thumbnail|portrait)|(no|without) (a |any )?(photo|headshot|picture|image|thumbnail|portrait)|carousel|slider|lazy|(not|fail\w*( to)?) load|cut off/i;
const ROLE = /^(noreply|no-reply|donotreply|do-not-reply|jobs|careers|career|hr|recruit\w*|events|media|press|marketing|billing|accounts|webmaster|postmaster|abuse|privacy|legal|support@?)$/i;
const REPLIED = /replied|unsubscrib|bounce|stop/i;
// Our own scraper being refused (403 / Cloudflare / "just a moment") is not a problem the clinic
// can see or fix, and we verified these sites return 200 to a normal browser. Rows written before
// this guard existed carry that false claim, so re-check it here instead of chasing it.
const BLOCKED = /\bforbidden\b|\baccess denied\b|\bcloudflare\b|just a moment|checking your browser|attention required|site can'?t be reached|\b(40\d|5\d{2})\s*(error|forbidden|page|response|status)\b|\b(error|status)\s*(code\s*)?(40\d|5\d{2})\b/i;
const UNREACHABLE = /(site|website|homepage|web ?page|domain)\s+(is\s+)?(currently\s+)?(down|offline|unavailable|inaccessible|unreachable|not\s+(available|accessible|loading|working|reachable|functioning))/i;
const claimOf = r => [r.website_problem, r.recognisable_reason, r.consequence_mechanics].join(' ');

const blank = v => v === undefined || v === null || String(v).trim() === '';
const local = r => String(r['Email Address'] || '').split('@')[0].trim();
const key = r => String(r['Company Name'] || r.Domain || '').trim().toLowerCase();
const stageOf = r => ['Follow-up 1', 'Follow-up 2', 'Follow-up 3'].filter(c => !blank(r[c])).length;

// Lower rank wins: a named person, then a front-desk style inbox, then anything else.
function rank(r) {
  if (!blank(r['First name'])) return 0;
  if (/^(info|contact|office|hello|smile|frontdesk|front-desk|reception|admin|dental|clinic)$/i.test(local(r))) return 1;
  return 2;
}

const rows = $input.all().map(i => i.json);

// One clinic, one conversation. Several addresses at the same clinic all got a first email before
// the dedup landed; following up on every one of them would read as spam.
const byCompany = {};
rows.forEach(r => { (byCompany[key(r)] = byCompany[key(r)] || []).push(r); });

const cand = [];
Object.keys(byCompany).forEach(k => {
  const group = byCompany[k];
  // Anyone at the clinic answering ends outreach for the whole clinic.
  if (group.some(r => !blank(r.Issues) && REPLIED.test(String(r.Issues)))) return;
  const live = group.filter(r =>
    !blank(r.ThreadID)
    && blank(r['Stop-30'])
    && blank(r.Issues)
    && !ROLE.test(local(r))
    && stageOf(r) < 3
    && !ARTIFACT.test(String(r.website_problem || '')) // the claim itself was a screenshot artifact
    && !BLOCKED.test(claimOf(r)) && !UNREACHABLE.test(claimOf(r)) // our scraper was blocked, the site is fine
  );
  if (!live.length) return;
  live.sort((a, b) => rank(a) - rank(b) || Number(a.row_number) - Number(b.row_number));
  cand.push(live[0]);
});

cand.sort((a, b) => Number(a.row_number) - Number(b.row_number));
return cand.slice(0, 12).map(json => ({ json }));

// FU Decide — one follow-up per run, chosen from the threads FU Thread just read.
// The sheet has no "date sent" column, so cadence comes from Gmail itself: days since our own last
// message in the thread. That also makes the branch self-correcting if a run is missed.
// Gaps match the old wait chain: follow-up 2 at +3 days, 3 at +2, 4 at +2.
const GAPS = [3, 2, 2];
// Same banned list as the research quality gate: invented metrics and agency jargon.
const BANNED = /\d+\s*%|\b\d+\+|bounce|conversion|revenue|\broi\b|decision fatigue|choice overload|analytics|guarantee|funnel|optimi[sz]/i;

const rows = $('FU Pick').all().map(i => i.json);
const threads = $input.all().map(i => i.json);
const blank = v => v === undefined || v === null || String(v).trim() === '';
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const labelsOf = m => (m.labelIds || (m.labels || []).map(l => (l && l.id) || l) || []).map(String);
// Cells are packed "full || short"; index 1 is the tightened variant, index 0 the original.
const part = (r, f, i) => {
  const bits = String(r[f] || '').split(' || ');
  return (bits[i] || bits[0] || '').trim();
};
const stageOf = r => ['Follow-up 1', 'Follow-up 2', 'Follow-up 3'].filter(c => !blank(r[c])).length;
const today = new Date().toISOString().slice(0, 10);

for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  const t = threads[i];
  if (!t || t.error || !Array.isArray(t.messages) || !t.messages.length) continue;

  const msgs = t.messages;
  const sent = msgs.filter(m => labelsOf(m).includes('SENT'));
  if (!sent.length) continue;
  // Anything in the thread that is not ours ends the sequence — real reply or auto-reply alike.
  if (msgs.some(m => !labelsOf(m).includes('SENT'))) continue;

  const lastSent = Math.max.apply(null, sent.map(m => Number(m.internalDate) || 0));
  if (!lastSent) continue;
  const days = (Date.now() - lastSent) / 86400000;

  // The thread is the truth about how many we have actually sent; the sheet can lag it.
  const stage = Math.max(stageOf(r), sent.length - 1);
  if (stage >= 3) continue;
  if (days < GAPS[stage]) continue;

  const name = blank(r['First name']) ? 'there' : String(r['First name']).trim();
  const company = String(r['Company Name'] || 'your clinic').trim();
  const micro = blank(r.micro_yes) ? 'Want me to send it over?' : String(r.micro_yes).trim();
  const doctrine = String(r.website_problem || '').includes(' || ');

  const closing = '<p>Hi ' + esc(name) + ',</p>'
    + '<p>Closing the loop on this one.</p>'
    + '<p>Want me to send the free preview for ' + esc(company) + '?</p>'
    + '<p>Your Name</p>';

  let body;
  if (!doctrine) {
    // Researched before the doctrine rewrite: that older text is exactly what the quality gate now
    // rejects, so quote none of it — send the short closing note and retire the row.
    body = closing;
  } else if (stage === 0) {
    body = '<p>Hi ' + esc(name) + ',</p>'
      + '<p>One more thought on the ' + esc(r.page || 'website') + ' page.</p>'
      + '<p>' + esc(part(r, 'recognisable_reason', 1)) + '</p>'
      + '<p>' + esc(part(r, 'consequence_mechanics', 1)) + '</p>'
      + '<p>The preview would show that one change. ' + esc(micro) + '</p>'
      + '<p>Your Name</p>';
  } else if (stage === 1) {
    body = '<p>Hi ' + esc(name) + ',</p>'
      + '<p>Last note from me on this.</p>'
      + '<p>The preview covers one thing: ' + esc(part(r, 'website_problem', 1)) + '.</p>'
      + '<p>About ' + (Number(r.review_time) || 3) + ' minutes to judge.</p>'
      + '<p>' + esc(micro) + '</p>'
      + '<p>Your Name</p>';
  } else {
    body = closing;
  }
  if (BANNED.test(body)) body = closing;

  const last = stage === 2 || !doctrine || body === closing;
  const stamp = 'Sent ' + today;
  const out = {
    row_number: r.row_number,
    company: company,
    to: r['Email Address'] || '',
    threadId: String(r.ThreadID).trim(),
    messageId: msgs[msgs.length - 1].id,
    stage: stage + 2, // human-readable: this is follow-up 2, 3 or 4
    days: Math.round(days * 10) / 10,
    body: body,
    fu1: blank(r['Follow-up 1']) ? (stage === 0 ? stamp : '') : String(r['Follow-up 1']),
    fu2: blank(r['Follow-up 2']) ? (stage === 1 ? stamp : '') : String(r['Follow-up 2']),
    fu3: blank(r['Follow-up 3']) ? (stage === 2 ? stamp : '') : String(r['Follow-up 3']),
    stop30: last ? 'Done ' + today : ''
  };
  if (!out.threadId || !out.messageId || !out.body) continue;
  return [{ json: out }];
}

return [];
